#include <vector>
#include <deque>
#include <algorithm>

class Solution {
public:
    int maxTaskAssign(std::vector<int>& tasks, std::vector<int>& workers, int pills, int strength) {
        std::sort(tasks.begin(), tasks.end());
        std::sort(workers.begin(), workers.end());

        auto canAssign = [&](int k) -> bool {
            if (k == 0) return true;
            std::deque<int> q;
            int p = pills;
            int wIdx = k - 1;
            int m = workers.size();

            for (int i = k - 1; i >= 0; --i) {
                int task = tasks[i];
                while (wIdx >= 0 && workers[m - k + wIdx] + strength >= task) {
                    q.push_front(workers[m - k + wIdx]);
                    wIdx--;
                }

                if (q.empty()) return false;

                if (q.back() >= task) {
                    q.pop_back();
                } else {
                    if (p == 0) return false;
                    p--;
                    q.pop_front();
                }
            }
            return true;
        };

        int low = 0, high = std::min(tasks.size(), workers.size());
        int ans = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canAssign(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);

        int low = 0, high = Math.min(tasks.length, workers.length);
        int ans = 0;

        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (canAssign(mid, tasks, workers, pills, strength)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private boolean canAssign(int k, int[] tasks, int[] workers, int pills, int strength) {
        if (k == 0) return true;
        Deque<Integer> q = new ArrayDeque<>();
        int p = pills;
        int wIdx = k - 1;
        int m = workers.length;

        for (int i = k - 1; i >= 0; i--) {
            int task = tasks[i];
            while (wIdx >= 0 && workers[m - k + wIdx] + strength >= task) {
                q.offerFirst(workers[m - k + wIdx]);
                wIdx--;
            }

            if (q.isEmpty()) return false;

            if (q.peekLast() >= task) {
                q.pollLast();
            } else {
                if (p == 0) return false;
                p--;
                q.pollFirst();
            }
        }
        return true;
    }
}

