var maxTaskAssign = function(tasks, workers, pills, strength) {
    tasks.sort((a, b) => a - b);
    workers.sort((a, b) => a - b);

    const canAssign = (k) => {
        if (k === 0) return true;
        const q = [];
        let head = 0;
        let p = pills;
        let wIdx = k - 1;
        const m = workers.length;

        for (let i = k - 1; i >= 0; i--) {
            const task = tasks[i];
            while (wIdx >= 0 && workers[m - k + wIdx] + strength >= task) {
                q.push(workers[m - k + wIdx]);
                wIdx--;
            }

            if (head >= q.length) return false;

            if (q[head] >= task) {
                head++;
            } else {
                if (p === 0) return false;
                p--;
                q.pop();
            }
        }
        return true;
    };

    let low = 0, high = Math.min(tasks.length, workers.length);
    let ans = 0;

    while (low <= high) {
        const mid = (low + high) >> 1;
        if (canAssign(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
